#pragma once
// Scene "marble" (ray_tracing_windows_desktop_wallpaper.md):
// black marble floor + 3 quartz spheres moved by OpenSimplex2 noise (FastNoiseLite) + 2 neon lights.
#include "Scene.hpp"
#include "FastNoiseLite.hpp"
#include "Marble.hlsl.h"   // generated by dxc: g_pMarble[]

class MarbleScene : public Scene
{
    // Must match SceneConstantBuffer in shaders/Marble.hlsl (all float4 => no padding issues).
    struct Constants
    {
        CameraConstants camera;
        DirectX::XMFLOAT4 spherePositions[3]; // xyz, w = radius
        DirectX::XMFLOAT4 lightPositions[2];
        DirectX::XMFLOAT4 lightColors[2];     // rgb, w = intensity
        DirectX::XMFLOAT4 params;             // x = time
    };

    FastNoiseLite m_noiseX, m_noiseY, m_noiseZ;
    float m_timeAcc = 0.0f;

public:
    MarbleScene()
    {
        FastNoiseLite* n[3] = { &m_noiseX, &m_noiseY, &m_noiseZ };
        const int seeds[3] = { 1337, 4242, 9999 };
        for (int i = 0; i < 3; i++)
        {
            n[i]->SetNoiseType(FastNoiseLite::NoiseType_OpenSimplex2);
            n[i]->SetSeed(seeds[i]);
            n[i]->SetFrequency(0.15f);
        }
    }

    const wchar_t* Name() const override { return L"marble"; }
    D3D12_SHADER_BYTECODE Library() const override { return { g_pMarble, sizeof(g_pMarble) }; }
    UINT InstanceCount() const override { return 4; }
    UINT MaxRecursion() const override { return 6; }   // MAX_DEPTH (5) + 1

    std::vector<HitGroupDef> HitGroups() const override
    {
        return {
            { L"FloorHitGroup", L"FloorClosestHit", nullptr },
            { L"SphereHitGroup", L"QuartzClosestHit", L"SphereIntersection" },
        };
    }

    std::vector<GeometryDef> Geometry() const override
    {
        const float s = 200.0f;
        GeometryDef floor;
        floor.procedural = false;
        floor.vertices = { -s, 0, -s,  -s, 0, s,  s, 0, s,   -s, 0, -s,  s, 0, s,  s, 0, -s };
        GeometryDef sphere;
        sphere.aabb = { -1, -1, -1, 1, 1, 1 };
        return { floor, sphere };
    }

    UINT Update(float deltaTime, float, void* constants, InstanceDef* instances) override
    {
        using namespace DirectX;
        Constants& cb = *static_cast<Constants*>(constants);
        m_timeAcc += deltaTime;
        const float t = m_timeAcc;

        // Independent procedural motion for each sphere (radius = 1).
        for (int i = 0; i < 3; i++)
        {
            float offset = i * 100.0f;
            float x = m_noiseX.GetNoise(t + offset, 0.0f) * 4.0f;
            float y = 1.2f + fabsf(m_noiseY.GetNoise(t + offset, 50.0f)) * 2.0f; // float above the floor
            float z = m_noiseZ.GetNoise(t + offset, 100.0f) * 3.0f;
            cb.spherePositions[i] = XMFLOAT4(x, y, z, 1.0f);
        }

        // Neon lights: cobalt blue and warm amber.
        cb.lightPositions[0] = XMFLOAT4(-5.0f, 4.0f, sinf(t * 0.5f) * 3.0f, 1.0f);
        cb.lightPositions[1] = XMFLOAT4( 5.0f, 4.0f, cosf(t * 0.5f) * 3.0f, 1.0f);
        cb.lightColors[0]    = XMFLOAT4(0.0f, 0.4f, 1.0f, 10.0f);
        cb.lightColors[1]    = XMFLOAT4(1.0f, 0.5f, 0.0f, 10.0f);

        // Slow camera sway around the scene.
        float a = sinf(t * 0.05f) * 0.45f;
        cb.camera = MakeCamera(XMVectorSet(sinf(a) * 10.5f, 3.4f + sinf(t * 0.11f) * 0.3f, cosf(a) * 10.5f, 0),
                               XMVectorSet(0.0f, 1.4f, 0.0f, 0), 48.0f);
        cb.params = XMFLOAT4(t, 0, 0, 0);

        // Instance 0 = floor, 1..3 = spheres.
        instances[0] = InstanceDef{ 0, 0, 0 };
        for (UINT i = 0; i < 3; i++)
        {
            const XMFLOAT4& p = cb.spherePositions[i];
            instances[i + 1] = InstanceDef{ 1, 1, i };
            instances[i + 1].SetTranslationScale(p.x, p.y, p.z, p.w);
        }
        return sizeof(Constants);
    }
};
